-- Generated by scripts/generate-ai-case-catalog-sql.mjs.
-- The canonical source is data/ai-public-cases.json.

create table if not exists public.ai_knowledge_clients (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  slug text not null unique,
  name text not null,
  aliases jsonb not null default '[]'::jsonb,
  published boolean not null default true
);

create table if not exists public.ai_knowledge_cases (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  slug text not null unique,
  client_id uuid references public.ai_knowledge_clients(id) on delete set null,
  display_name text not null,
  vertical text not null,
  category text not null,
  title text not null,
  summary text not null,
  task text not null,
  solution text not null,
  result text not null,
  tags jsonb not null default '[]'::jsonb,
  public_url text not null,
  sort_order integer not null default 0,
  published boolean not null default true
);

create table if not exists public.ai_knowledge_case_aliases (
  case_id uuid not null references public.ai_knowledge_cases(id) on delete cascade,
  alias text not null,
  normalized_alias text not null,
  primary key (case_id, normalized_alias)
);

create table if not exists public.ai_knowledge_claims (
  id uuid primary key default gen_random_uuid(),
  case_id uuid not null references public.ai_knowledge_cases(id) on delete cascade,
  kind text not null check (kind in ('summary', 'task', 'solution', 'result')),
  content text not null,
  source_url text not null,
  published boolean not null default true,
  unique (case_id, kind)
);

create table if not exists public.ai_knowledge_assets (
  id uuid primary key default gen_random_uuid(),
  case_id uuid not null references public.ai_knowledge_cases(id) on delete cascade,
  kind text not null check (kind in ('case_page', 'image', 'video', 'document')),
  label text not null,
  url text not null,
  published boolean not null default true,
  verified_at timestamptz not null default now(),
  unique (case_id, kind, url)
);

create index if not exists ai_knowledge_cases_vertical_idx
  on public.ai_knowledge_cases(vertical, published, sort_order);
create index if not exists ai_knowledge_aliases_normalized_idx
  on public.ai_knowledge_case_aliases(normalized_alias);

alter table public.ai_knowledge_clients enable row level security;
alter table public.ai_knowledge_cases enable row level security;
alter table public.ai_knowledge_case_aliases enable row level security;
alter table public.ai_knowledge_claims enable row level security;
alter table public.ai_knowledge_assets enable row level security;

revoke all on table public.ai_knowledge_clients from anon, authenticated;
revoke all on table public.ai_knowledge_cases from anon, authenticated;
revoke all on table public.ai_knowledge_case_aliases from anon, authenticated;
revoke all on table public.ai_knowledge_claims from anon, authenticated;
revoke all on table public.ai_knowledge_assets from anon, authenticated;
grant all on table public.ai_knowledge_clients to service_role;
grant all on table public.ai_knowledge_cases to service_role;
grant all on table public.ai_knowledge_case_aliases to service_role;
grant all on table public.ai_knowledge_claims to service_role;
grant all on table public.ai_knowledge_assets to service_role;

create or replace function public.ai_normalize_search_text(value text)
returns text
language sql
immutable
parallel safe
as $$
  select trim(regexp_replace(replace(lower(coalesce(value, '')), 'ё', 'е'), '[^a-zа-я0-9]+', ' ', 'g'));
$$;

