insert into public.ai_knowledge_cases (
  slug, client_id, display_name, vertical, category, title,
  summary, task, solution, result, tags, public_url, sort_order, published
)
select
  input.slug, client.id, input.display_name, input.vertical, input.category,
  input.title, input.summary, input.task, input.solution, input.result,
  input.tags, input.public_url, input.sort_order, input.published
from input
left join public.ai_knowledge_clients as client on client.slug = input.client_slug
on conflict (slug) do update set
  client_id = excluded.client_id,
  display_name = excluded.display_name,
  vertical = excluded.vertical,
  category = excluded.category,
  title = excluded.title,
  summary = excluded.summary,
  task = excluded.task,
  solution = excluded.solution,
  result = excluded.result,
  tags = excluded.tags,
  public_url = excluded.public_url,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

