insert into public.ai_knowledge_case_aliases (case_id, alias, normalized_alias)
select case_record.id, input.alias, public.ai_normalize_search_text(input.alias)
from input
join public.ai_knowledge_cases as case_record on case_record.slug = input.case_slug
on conflict (case_id, normalized_alias) do update set alias = excluded.alias;

