insert into public.ai_knowledge_claims (case_id, kind, content, source_url, published)
select case_record.id, input.kind, input.content, input.source_url, input.published
from input
join public.ai_knowledge_cases as case_record on case_record.slug = input.case_slug
on conflict (case_id, kind) do update set
  content = excluded.content,
  source_url = excluded.source_url,
  published = excluded.published;

