insert into public.ai_knowledge_assets (case_id, kind, label, url, published)
select case_record.id, input.kind, input.label, input.url, input.published
from input
join public.ai_knowledge_cases as case_record on case_record.slug = input.case_slug
on conflict (case_id, kind, url) do update set
  label = excluded.label,
  published = excluded.published,
  verified_at = now();

create or replace function public.search_ai_public_cases(
  query_text text default '',
  filter_vertical text default null,
  match_count integer default 10
)
returns table (
  id uuid,
  slug text,
  display_name text,
  client_name text,
  vertical text,
  category text,
  title text,
  summary text,
  task text,
  solution text,
  result text,
  tags jsonb,
  public_url text,
  assets jsonb,
  exact_match boolean,
  retrieval_score double precision
)
language sql
stable
security definer
set search_path = public
as $$
  with query as (
    select public.ai_normalize_search_text(query_text) as normalized
  ), ranked as (
    select
      case_record.*,
      client.name as client_name,
      coalesce(max(
        case when query.normalized <> '' and position(
          ' ' || alias.normalized_alias || ' ' in ' ' || query.normalized || ' '
        ) > 0 then 1 else 0 end
      ), 0) = 1 as exact_match,
      coalesce(max(
        case when query.normalized <> '' and position(
          ' ' || alias.normalized_alias || ' ' in ' ' || query.normalized || ' '
        ) > 0 then 100.0 else 0.0 end
      ), 0.0) +
      ts_rank_cd(
        to_tsvector('simple', concat_ws(' ', case_record.display_name, case_record.title, case_record.summary, case_record.tags::text)),
        plainto_tsquery('simple', query.normalized),
        32
      ) * 10.0 as retrieval_score
    from public.ai_knowledge_cases as case_record
    cross join query
    left join public.ai_knowledge_clients as client on client.id = case_record.client_id
    left join public.ai_knowledge_case_aliases as alias on alias.case_id = case_record.id
    where case_record.published = true
      and (filter_vertical is null or case_record.vertical = filter_vertical)
    group by case_record.id, client.name, query.normalized
  )
  select
    ranked.id,
    ranked.slug,
    ranked.display_name,
    ranked.client_name,
    ranked.vertical,
    ranked.category,
    ranked.title,
    ranked.summary,
    ranked.task,
    ranked.solution,
    ranked.result,
    ranked.tags,
    ranked.public_url,
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', asset.id,
        'kind', asset.kind,
        'label', asset.label,
        'url', asset.url
      ) order by case asset.kind when 'case_page' then 1 when 'video' then 2 else 3 end)
      from public.ai_knowledge_assets as asset
      where asset.case_id = ranked.id and asset.published = true
    ), '[]'::jsonb) as assets,
    ranked.exact_match,
    ranked.retrieval_score
  from ranked
  where public.ai_normalize_search_text(query_text) = ''
    or ranked.exact_match
    or ranked.retrieval_score > 0.01
  order by ranked.exact_match desc, ranked.retrieval_score desc, ranked.sort_order
  limit greatest(1, least(match_count, 30));
$$;

revoke all on function public.search_ai_public_cases(text, text, integer)
  from public, anon, authenticated;
grant execute on function public.search_ai_public_cases(text, text, integer)
  to service_role;
